window.ECE_CURRICULUM_DETAILS = window.ECE_CURRICULUM_DETAILS || {};
for (const [code, chapters] of Object.entries(window.ECE_CURRICULUM_USER)) {
  window.ECE_CURRICULUM_DETAILS[code] = { ...window.ECE_CURRICULUM_DETAILS[code], chapters: chapters.map((chapter, index) => ({
    number: String(index + 1), title: chapter[0],
    subtopics: chapter[1] ? chapter[1].split('; ') : []
  })) };
}
